values
  ($NT$Omukama's Crown$NT$, 'Batooro', 'Headwear',
   $NT$Circa 1890, symbol of sovereign authority and spiritual protection.$NT$,
   $NT$Handcrafted crown worn by the Omukama (King) of Tooro Kingdom during royal accession ceremonies. Adorned with intricate beadwork in royal gold, crimson, and ivory beads, passed down through sovereign generations.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuBU1V0R0EcgLw1sZnnZN8-x2NBcTA62n10uL-nOgNA5E5xt_p5vpMEvMgSNu63pOqcBfJO0N5dzSlbID1Co44K_Xrkf1o6idI4ZP4wRLIZxBvXsOePdtMiAOHeA9cLCgwyslL5qDB8VzPFA9fitXFkDLiQO5wMybsG4fWtkrSw0ECaE19R9jzo4C8vHZDAJnySMh7HBWoHj3A2QOVdBd7wthb9mTBdYZ-mF6b8LS9xdI6KxU-KIJRUaLg$NT$,
   '19th Century', $NT$Glass beads, leather, velvet, brass wire$NT$, $NT$Tooro Kingdom, Western Uganda$NT$,
   $NT$Embodies the divine ancestral seal of the Omukama, protecting the nation from misfortune.$NT$, true, 'reg-omukama-crown'),
  ($NT$Brass Adornments$NT$, 'Ankole', 'Jewelry',
   $NT$Crafted symbols of wealth and social status from Western Uganda.$NT$,
   $NT$Heavy hand-poured brass bangles and neckpieces worn by noble Bahima women during weddings and royal gatherings. The shiny brass patina reflects sunlight across the pasture lands.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuDoDprzjAh9EW1VKS7A9QFNiFOR8HFMlrhu8NDxRHpFYVI_LbMx0HLZyTCdpojUD4ias3OL2HYmBviPzBzMAq8PBXyBuKPduu8eyWigK25I5TMCzvhv-bqso9rhITSljysUMPcQRyROvXCkyqQZFGNwpBdHWYE_jEJoP3rLEOON8T7Hkb5MJxc4YkX72J3UBlb311V-00-6XnCfTBseIweXMOq1WwDrgYYj8pRrgnIwYf7683lGiKEcgA$NT$,
   'Late 19th Century', $NT$Poured brass, copper alloy, linen weave$NT$, $NT$Ankole Kingdom, South-Western Uganda$NT$,
   $NT$Bestows prosperity, blessing for herd fertility, and marital dignity.$NT$, true, 'reg-brass-adornments'),
  ($NT$Traditional Gomesi$NT$, 'Buganda', 'Garments',
   $NT$A ceremonial silk garment known for its elegant square neckline and sash.$NT$,
   $NT$The floor-length attire with iconic puffed shoulders and broad silk sash (Ekitambala). Worn across Central Uganda for official royal visits, Kwanjula introduction ceremonies, and state celebrations.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuBuQ3mt3yKNbs8Ya41h0M-AY48rNc44B_u-qktGO6FnmQdgPs76jhgCLvlGxD9ts303xEvC_23sRpcTaA20USi1PEghwVNXfybebvwuaLITK-nJot505MbHpIZW8jBfUNZC56PK71bvkwkixfnGuLDKsr7mM5gjIM0DP4qCNUZfbOCzLSvZI1b3_rhh7NKEf0zgHvX8j5Jm3mLpViCd8e8EZsL0tsNVFm5zloLh9DFc9NMw66W1YT9MbQ$NT$,
   'Early 20th Century to Present', $NT$Woven silk, satin, cotton lining$NT$, $NT$Buganda Kingdom, Central Uganda$NT$,
   $NT$Represents feminine grace, cultural fidelity, and royal etiquette.$NT$, false, 'reg-traditional-gomesi'),
  ($NT$Enchoro Necklace$NT$, 'Maasai', 'Jewelry',
   $NT$Handcrafted glass beadwork representing age sets and social status.$NT$,
   $NT$Vibrant concentric beaded collar necklace woven with symbolic primary colors: red for bravery, blue for sky/rain, yellow for sun, and white for purity.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuCx_hv7JsZzHRljsjKbBkeSnA6f896iQDBzpOxt80SyDGhiCbtHwTRUUod_jTifmzKyMrIh3tkBw4yWO0Arq8SWi3ooCngdPxoCZmp4aWH9UHenEHlcHXmbEqNs0_MVXJJL6pxw0duwBDHYlTf72bsAYXcbpEFGifd4ivltQ3wTCahr0_7M3qiUz8sjJLfomNw3iDtq1I_6qA79k7VKdesv_U5MqhqUsm6UtZ5PZELwlvgzg59oRcFzlw$NT$,
   'Mid 20th Century', $NT$Glass beads, sinew, recycled wire$NT$, $NT$East African Rift Valley$NT$,
   $NT$Identifies the wearer's age grade, marital standing, and clan lineage.$NT$, false, 'reg-enchoro-necklace'),
  ($NT$Ancestral Kanzu$NT$, 'Central Africa', 'Garments',
   $NT$The cream-colored tunics of dignity, often paired with a blazer.$NT$,
   $NT$The iconic traditional tunic worn by men across Buganda, Busoga, and Tooro. Features meticulous maroon embroidery (Omulela) running along the neck and collar line.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuB18hazl_T9BRQ79LnPcNDhfZkQjiIY-aDvIsjHawGnnILVkPPYk_dXlo7hLspK0OvRWaWHk4h2-laDhCbjNEvNermiKELHSB_gXXywT4MtaQ5XzZmwkuYkVyOkgHJ5Tx71BLJuHpGZTt72WtpXJxKggjsCM1oHR0wQOMxwngDWsGcZTkNqh9Ht7VtL01Dagof3LNOPdWPSU8_W3lkNtdVneyanUY5bdIkeXPPY9pFFVow_3bcMYC7twQ$NT$,
   '19th Century', $NT$Fine linen, silk thread embroidery$NT$, $NT$Central Uganda & Great Lakes$NT$,
   $NT$Symbol of male statesman honor, integrity, and elder wisdom.$NT$, false, 'reg-ancestral-kanzu'),
  ($NT$Noopile Hat$NT$, 'Fulani', 'Headwear',
   $NT$A conical woven straw hat adorned with dyed leather and geometric patterns.$NT$,
   $NT$Protective and ceremonial conical hat woven from wild grasses and bound with hand-dyed dark red and brown leather strips.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuAZkF4eeblK4ZE3VI6a-76D9gf8Q6-MqnlKgIQ0tFEh1nNZkUoKywen-BTdCSyjjFpOUgsPZumv9qUsK27yCxJHa_s5dtDcG6HMvCmE4HBiVAxNlt7UUga9-z29VPqebjXIR_SZOVGa3RXgkhXeoRKOc0_znnprn_KWFZaMlw2g1bo-pKgYLtksGvPslRYi7rBFmX-St0kDjnrPer8T9poWvLMyJj_DCLUkAxvCsSie7fYVnszBCpl_Yg$NT$,
   'Circa 1920', $NT$Natural grass straw, tanned goatskin leather$NT$, $NT$Sahel & Savanna Belt$NT$,
   $NT$Protects pastoral travelers under intense solar heat while symbolizing nomadic freedom.$NT$, false, 'reg-noopile-hat'),
  ($NT$Royal Kente$NT$, 'Asante', 'Garments',
   $NT$Hand-woven strips of silk and cotton with symbolic geometric motifs.$NT$,
   $NT$Master weaver cloth using traditional narrow-strip looms. Each geometric grid pattern encodes proverbs, royal history, and philosophical concepts.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuDQADVp57HjA_KhXL6dxKKlgjZvh8evwWr1ymixFTo_AyVdWvJNT-t5nRHFkTpErQRHPrLNbMLfRIS3H5agpcR7rfS-Q5JedwpMLRIrrfa8WRsZQjpf5O2RLbN0HoDekcMqMT5TTgG5iDEFWb5S61LL2Xmp_aHpyYuCyDH0JShOjLeKG5gzjoIAjufzkdvfUoMgI0Cvp_I21oxjiGsMaFZQWMtZPeHb178AD4UoCOHZI2Tb28yD4jxBAQ$NT$,
   '18th Century Heritage', $NT$Pure silk thread, organic dyed cotton$NT$, $NT$West African Coast$NT$,
   $NT$Sacred garment reserved for paramount chiefs and life transition rituals.$NT$, false, 'reg-royal-kente'),
  ($NT$Agadez Cross$NT$, 'Tuareg', 'Jewelry',
   $NT$A silver talisman representing navigation and family lineage in the Sahara.$NT$,
   $NT$Lost-wax cast silver pendant incorporating the four cardinal directions and stellar constellation map points used by desert caravans.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuC0YEbMS3vISYWHDhMg34vcutRROESXbg_njX6x-NV6uHlawIWJhaJYJb-n-B-7WLMus1nZFxSx1lZNTtydlz6UXd6Gd2r7jFGD7TOn8njR-uYU8r9lTNqFb8tTcR1kR3xD53HjgiI8_huZ78QzL6FC1l4LlglfTNzN6pIMwnQ9fOG-EGBmnaK_xevvdbxMPbzWS3OsOIFBKPT5JVuRpr6xtEcMGZxQX6FPiAdC2_PSvqwQ9GPA_i4aAw$NT$,
   '19th Century', $NT$Hand-chased pure silver, indigo linen thread$NT$, $NT$Saharan Highlands$NT$,
   $NT$Protective amulet passed from father to son upon reaching manhood.$NT$, false, 'reg-agadez-cross'),
  ($NT$Isicholo Headdress$NT$, 'Zulu', 'Headwear',
   $NT$A traditional flared hat representing maturity and social status.$NT$,
   $NT$Woven flared crown colored with natural red ochre pigments and structural woven grass. Worn exclusively by married women during ceremonial dances.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuA3MgOXVnjN-7n8fUSMKiOj7H3c_K704qnsqSDzm0z_PUfkUIZlvI_mvSO9gh9E9dCw1aq0eFvkBszboI7ddXngSKNOVoH9TyibkKKpAoRoYLNv2AgBx9kgs2Ec1QgPkQoJaRBDh3ljT5LZNvG5A7Af6bYDg7TqWF82lePWyTEjVv_qfogd-OkarRgHmg9tgCVQTqksHWcMfHTLp5clOaQFH-nvw8LvYtYiBYaeYef1PKQKPaypAUsI8w$NT$,
   'Early 20th Century', $NT$Wild grass weave, red ochre pigment, cotton thread$NT$, $NT$Southern Africa$NT$,
   $NT$Demonstrates dignity, matronly wisdom, and commitment to hearth and family.$NT$, false, 'reg-isicholo-headdress'),
  ($NT$Ceremonial Beads$NT$, 'Acholi', 'Jewelry',
   $NT$Sacred ornamentation worn during cultural rites of passage.$NT$,
   $NT$Multi-stranded waist and neck beads crafted from carved bone, seeds, and semi-precious stone beads worn during harvest thanksgiving festivals.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuBDMl-QoG1jHezoSYJ7rnKgRNtBO31TnXID9tG-tsPZLxZ7y5_cRmz8Co23d9_tNPobgMhczjqR8jZADVVZAc8EOfF1Uy5Hf_dGC0EnU46aJsKamWiV_DZ1Lge6D-X3SCpzISZyr4H0b3NiX12jwYwGioXwPoQMmOkwrT5qOc-R-ieXUpXQG-gjkzKj3tmvZdIX6p04uUknoFz2pixph4QNER140_c5DQ9HerTHrSOy-qjLNe9ySNOURA$NT$,
   '19th Century', $NT$Natural bone, polished seeds, stone, cowrie shells$NT$, $NT$Northern Uganda$NT$,
   $NT$Anchors youth to ancestral guidance during coming-of-age ceremonies.$NT$, false, 'reg-ceremonial-beads'),
  ($NT$Warrior Shield$NT$, 'Acholi', 'Ceremonial',
   $NT$Intricate hide patterns representing kinship and battle honors.$NT$,
   $NT$Crafted from seasoned buffalo hide with hand-forged iron reinforcements and brass wire bindings. Used in traditional royal guard ceremonies and ceremonial dance rituals (Larakaraka).$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuACKxHlWMB3LGLk5MiUPIa6G1-3B3LM8h7nqc49jeZaEC0WJGqyF3eq62wUbC6qPa_HAWBoB3Zdkj_fLh5TjyDawjZYEdPyEDGNvRsdV-8kSOUxXmsDOWJZYyRcH1FHofpeuXXtc3wl_b6iEUV24vJD7KjvNpW5lnxo5QpuY2mK79u-tSoZY5Se4rt2_-U8DUhMS07DtbZFoe1CHWE_jKKZZsdzPTgdYwC7uZrPsepp8DH7Sk4Wf84ovA$NT$,
   'Circa 1900', $NT$Cattle hide, hand-forged iron, wooden spine$NT$, $NT$Northern Region, Uganda$NT$,
   $NT$Carries clan crest markings signifying courage, defense of homesteads, and ancestral guardianship.$NT$, true, 'reg-warrior-shield');

