  ($NT$Royal Talking Drums (Atumpan)$NT$, 'Akan Heritage', '#NT-2042', 'Late 18th Century', 'Central Region, Ghana',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuBuquU3ZFYnlBJiYIKUOW7gwG0EcIGKPleknvsKPQQy_RzaXygcKA7rl8ohs3MeXpkgI-Fvw7uEvZYv2D5niGGaHjQpLzrV_YSjDrhvSae72pyn1YEYBOR8EuRITxYoOVjTYgM7kZf6XAYvcA7a8_ACxts9zg6PHJULE-fLJi7dJbGxvWsasCy4mNm7gezGic1kGuqFPuZTtVvZg1QvWDYWmKcpeXlZXZwzR64K5-bZttTxem0mkiBW8g$NT$,
   $NT$Master pair of open goblet drums carved from a single hollowed log of Tweneboa wood, tuned with elephant hide and peg tensioners.$NT$,
   $NT$Polished hardwood, stretched hide, brass pegs, copper wire$NT$, 'ADDED 3 DAYS AGO',
   $NT$The Atumpan is the chief instrument for transmitting drum poetry, historical chronicles, and royal announcements across distances.$NT$,
   $NT$Played exclusively by master drummers (Kyerema) who were custodians of oral history and royal genealogies.$NT$,
   'talking_drums', 'art-talking-drums'),
  ($NT$Ancestral Vanguard Spears$NT$, 'Kongo Kingdom', '#NT-1088', 'Circa 1650 AD', 'Lower Congo River Basin',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuCWPTnwWRgrx3YfTkcX0xI2JUEvSmbiB6LkxZLBxUeFEIktvOmGKWAOy_0-Q3i5vYxeHXpWG2ITzVPSYJDAztCwmc2faAxbZorhWBzEUqbEdVcN9j9JgnheCFwg6Yj0XQGdvW_HkHyqKSSn5qGF63_e-tZjJZUrty6kTQUwE25pihjjNouGVKO8MulGMHb_iUx_88j7y8kGujpxZ94p7R2NtsaBsx4dM6B4dggm3kp4dRHzHZTGEXsGUA$NT$,
   $NT$Forged iron spearheads with copper filigree spiral wraps along the shaft, preserved in court arsenals for ceremonial state marches.$NT$,
   $NT$Hand-forged iron, copper wire, African mahogany wood$NT$, 'ADDED 4 DAYS AGO',
   $NT$Emblematic of royal security, territorial sovereignty, and physical defense of clan boundaries.$NT$,
   $NT$Dating back to the height of the Kongo Kingdom, representing military discipline and blacksmithing mastery.$NT$,
   null, 'art-vanguard-spears'),
  ($NT$Terracotta Scholar Figure$NT$, 'Nok Culture', '#NT-0042', '500 BCE - 200 BCE', 'Kaduna State, Nigeria',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuDK3NEGPCvDboXHozJYRPrYXg6Q01cszAn2T4evzKYpvTgybCf7jQ8am-xrNmyt_VY5kwzTuxa8QU4hMoNqavhK2FBxK4Zsqt5PVjKQ8n6TMPFiuTFJiNz2avFcOE4MtVaOXu1qEEwzvD4wFqxNAscocz6niqhENQ2UGXibhSW8wuolVGQTqFiX98LCYXLUHESst9kdsXHu7nz8LNIiZKvpIgwztGBqsyDCgN4nGKbBfcSJ2u4DYdQR4g$NT$,
   $NT$Ancient hollow terracotta head featuring characteristic oval eyes, pierced pupils, and highly elaborate braided coiffure.$NT$,
   $NT$High-fired iron-bearing clay, natural ochre slip$NT$, 'ADDED 1 WEEK AGO',
   $NT$One of the earliest known sculptural traditions in Sub-Saharan Africa, testifying to sophisticated early iron-age urban centers.$NT$,
   $NT$Uncovered during tin mining operations in Nok village, revealing sophisticated terracotta kiln firing techniques.$NT$,
   null, 'art-terracotta-figure'),
  ($NT$Golden Rhinoceros Ornament$NT$, 'Great Zimbabwe Era', '#NT-9003', '13th Century', 'Limpopo Valley, South Africa',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuD5PnVhf5suoTHCBxJWp6KXiAc8yj1_k2yLzRAlo5tkClg8onkvxKSESJLqfoJJC9IARrnfgNgWMA_3bRKgOBz6MSwgmbPMIxPPSIpNQ1iMd3iRN_kplj3HKlwq7quJ6EbY4puUfz4v90V8ZpDBLJ8_ga8JeiS_AmN0lFIcNYPoKHKv7vmqSYsluHzbLngbb453UdAXqboWGHAmvW_xuB7Fd5rw--HlixkDssx_BMSPTNJVeyS8FfBl6A$NT$,
   $NT$Foil-hammered pure gold sheet wrapped over a carved wooden rhinoceros core with delicate gold tack fasteners.$NT$,
   $NT$Hammered gold foil, carved hardwood core, gold tacks$NT$, 'ADDED 2 WEEKS AGO',
   $NT$Symbol of monarchical power, solitary strength, and extensive trans-Indian Ocean gold trade routes.$NT$,
   $NT$Discovered at the royal burial site of Mapungubwe Hill, highlighting southern Africa's rich medieval gold civilization.$NT$,
   null, 'art-golden-rhino'),
  ($NT$Mbugu Tapestry$NT$, 'Baganda Heritage', '#NT-3011', 'Circa 1910', 'Central Uganda',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuAueui5xZKaxJBJzp_Mp0MLFgmK51LdPf9U7mf3bUGOpxlfb7knWdFTPu1hyYb3A-_jfXXni0w_PkzS7DcWKnh0wogk8tLuJWnG50d_GZQDcbTQ4DkoKmgfB-UU5mHBpLjyB3W-ggAx65z0ZVMuLhzGi8hnwH9AyOsVnyo0aGgfgvatdhrzwsjwwWOqF0PkotSKyuT9-xNip66Z5HDhobHQOR_BnEwvLEK-tXu76nLVubwMzhmU4AK-Uw$NT$,
   $NT$Ritual barkcloth harvested from Mutuba trees (Ficus natalensis) and decorated with hand-stenciled organic charcoal patterns.$NT$,
   $NT$Hammered tree bark, natural charcoal & earth pigments$NT$, 'ADDED 2 DAYS AGO',
   $NT$Recognized by UNESCO as a Masterpiece of the Oral and Intangible Heritage of Humanity.$NT$,
   $NT$Barkcloth making in Buganda is an ancient craft performed by hereditary royal artisans of the Ngonge clan.$NT$,
   null, 'art-mbugu-tapestry'),
  ($NT$Communal Libation Bowl$NT$, 'Bakiga / Kigezi', '#NT-4105', 'Late 19th Century', 'Kigezi Highlands, South-Western Uganda',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuA5AhtRpfyE6OQpb2-ApuXgxWG89UtOZ3hBR_BPRvxzvlmpXwXx49MoUKGVr7G9hY8nZ3T5VYt-fpBSnWzFP_s-sKH3x0sFZGkyS6QVDrIL916kae1-k2En_24TWZPD035eXLmZKfGwlGCKnnrv58FGsJTyJszNZjHNVYMJWdyMQPq5x_x_OWTGwOjKLlpC3Zc14AsYuyshbCEH2CJopRxJblGxTnU2LyCGanL1Yt9SlmNgpPRbP2Te5A$NT$,
   $NT$Hand-carved hardwood vessel from Kigezi used for pouring ancestral libations and communal sorghum beer share rites.$NT$,
   $NT$Carved African mahogany, beeswax seal$NT$, 'ADDED 5 DAYS AGO',
   $NT$Used during harvesting rites to pour the first drop of millet wine onto the earth in honor of clan elders.$NT$,
   $NT$Symbolizes communal unity, dispute resolution, and spiritual communion among highland clans.$NT$,
   null, 'art-communal-libation-bowl'),
  ($NT$Royal Ennanga$NT$, 'Buganda Kingdom', '#NT-5080', '19th Century', 'Court of Mutesa I, Kampala',
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuCsPYlKZhtxTcVs6_VlJViM7SZYdQvKQgcCCH9clzxoKx_HF1CTDgOyyYiwYFqfPWWQAesmq8C-DmF2__2PwH5u30tlYTGpfbhYahCW3MlKEam54UtayUcJSORW3DAIARZciHN1W9c-iQvEPmNQWWkg1A7n9EuESdF481JlPNxE0oEt9T3rU5oRKLGw3lroJq3aviDgVzbSh8i3cZuESpGYprWc7_lRx6Ux6sIWV4E-I01Q4mfxRj1XUQ$NT$,
   $NT$8-stringed royal harp curved from wood and resonant monitor lizard hide membrane, tuned to an pentatonic scale.$NT$,
   $NT$Resonant hardwood, monitor lizard skin, twisted fibre strings$NT$, 'ADDED 1 WEEK AGO',
   $NT$Played by court musicians to recount royal epics, heroic deeds of Kabakas, and moral allegories.$NT$,
   $NT$Restored instrument from the private collection of Kabaka Mutesa I of Buganda.$NT$,
   'ennanga_harp', 'art-royal-ennanga');

-- ---------- Communities (5) ----------
insert into public.communities
  (name, region, description, full_history, avatar_image, banner_image, population, language, royalty_leader, totems, key_traditions, slug)
values
  ('Baganda', 'Central Region',
   $NT$The largest ethnic group in Uganda, the Baganda belong to the Bantu-speaking people with a highly organized social and political system centered around the Kabaka (King). They are known for their deep-rooted traditions in barkcloth making, coffee farming, and vibrant oral literature.$NT$,
   $NT$The Kingdom of Buganda was founded in the 14th century by Kintu, the first Kabaka. Centered around the fertile shores of Lake Victoria, Buganda developed a sophisticated central administration, a naval fleet of war canoes, and a intricate clan system (Obwakabaka Bwa Buganda). Each clan maintains a specific hereditary role in the service of the Kabaka.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuCiNYokRgq7b9Col4s_Fxk5K7D0nVQQ0DxfQ8hAEd6di69U2TU1iWXDySDvVuyJGoSfnzR1anN6XBqMXfhIq78k77F6PirKwEALBgLPSc6CCQxJnQhXaKTS7Ul3YiW4E4Y2RUjHMb1rqcHrnBRJ3Wp13zAVAOX_rjRaAc5W2yWroa7F5sn-EB9XKcW22RYlt0suRSKiyIh0rhy3onCe6KB96JwVpPhOwMrawC0poXXAd700OusQL8THSg$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuCbT5D5jXTv5V0NWNdHI8okG9Ap23F9ZeaZvyXkQQzvu0Ugi6tIZRnerf25LPYdLAdVBL_TyWXswXwXNfZpvO37LCFsURK_ccIams951-IVN6eCAn8OEreIMpeAMTQVuBtZEozKuDfMIWyHxeXtc05V5obWpcxWZVf9va6n7zVzOgXySCJ57NdAjyZ_jHgTaCnk8kxl2K47scwpbDYLdMpAz_J0bcGWeuGqAaoAfuRm74ScWbZtWp7VkQ$NT$,
   '7.5+ Million', 'Luganda', 'His Majesty Kabaka Ronald Muwenda Mutebi II',
   $json$[{"name":"Pangolin","symbol":"🦎","meaning":"Protector of hidden wisdom","description":"The prime clan responsible for royal architectural carpentry.","lugandaName":"Lugave"},{"name":"Sheep","symbol":"🐑","meaning":"Gentleness and peace","description":"Custodians of royal barkcloth crafting.","lugandaName":"Ndiga"},{"name":"Ant","symbol":"🐜","meaning":"Industrious collective strength","description":"Master builders and agricultural planners.","lugandaName":"Kinyomo"},{"name":"Lion","symbol":"🦁","meaning":"Sovereign courage","description":"Guardians of royal military defense.","lugandaName":"Mpologoma"}]$json$::jsonb,
   $json$["Barkcloth Harvesting (Olubugo)","Bakisimba Court Dance","Introduction Ceremony (Kwanjula)","Royal Drums (Mujaguzo)"]$json$::jsonb,
   'com-baganda'),
  ('Karamojong', 'North Eastern Region',
   $NT$A Nilotic ethnic group of nomadic agro-pastoralists living in the semi-arid Karamoja region. Their culture is centered around cattle, which represent wealth and status. Known for their intricate beadwork, traditional manyattas (homesteads), and the famous "Ekizino" jumping dance.$NT$,
   $NT$Originating from the Ateker cluster that migrated from the Ethiopian highlands in the 16th century, the Karamojong survived harsh climate conditions through nomadic cattle herding. Their social organization is governed by the Akiriket council of elders.$NT$,
   $NT$https://lh3.googleusercontent.com/aida-public/AB6AXuAg_XybGJ5cKK1WKdeZ5t7MnZVmbZEijn-DKoXvsHGroSP_YEHaexfDBa63Yi4NTas_8Pw-vGeyP2S64v-dqcxwX1p1RJXr0UTA98M7qJeyQ08G3PRXiXMf_v6iCkCgXEIzk9ukAxDRO-0JyNnpqr9EeMgeJ1ZNazSSeiZV1zZxP7aPrIJ0frTCYRPZ_k8uovmKZx1XaUgA3rBMynlLmBoyGXFZlAON8AJPzNkOBz6AQkCfGaiKFkdvlA$NT$,
